solutions=[('billboards','Billboards & screens','Static spaces. Moving stories.','▣'),('metro','Metro & trains','Be part of the daily journey.','↔'),('television','Television','One story. A bigger stage.','▤'),('streaming','OTT & streaming','Meet them in the next episode.','▷'),('digital','Social & search','From the feed to the inbox.','↗')]
nav='''<header class="header"><a class="brand" href="index.html" aria-label="Primeboard home"><span class="brand-icon"><img src="primeboard-logo.png" alt="" width="512" height="512"></span>primeboard<sup>®</sup></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu ☰</button><nav id="navigation" aria-label="Main navigation"><details class="solutions-menu"><summary>Solutions <span>⌄</span></summary><div class="mega-menu"><div><span class="eyebrow">FIND YOUR NEXT AUDIENCE</span><h3>A world of<br>possibilities.</h3><p>Explore the spaces where your story can live.</p></div><div class="mega-links">'''+''.join(f'<a href="{slug}.html"><b>{icon}</b><span>{name}<small>{tag}</small></span><i>↗</i></a>' for slug,name,tag,icon in solutions)+'''</div></div></details><a href="platform.html">Platform</a><a href="partners.html">Media owners</a><a href="about.html">Company</a><a class="button small" href="about.html#contact">Let’s talk ↗</a></nav></header>'''
