def page(slug,title,description,content):
    (root/(slug+'.html')).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Primeboard</title><meta name="description" content="{html.escape(description,quote=True)}"><meta name="theme-color" content="#192cba"><link rel="icon" href="primeboard-logo.png"><link rel="stylesheet" href="site.css"><link rel="stylesheet" href="pages.css"><script src="pages.js" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a>{nav}<main id="main">{content}</main>{footer}</body></html>''',encoding='utf-8')
def hero(label,title,desc,tone='blue'):
    return f'<section class="page-hero {tone}"><div class="breadcrumbs"><a href="index.html">Home</a> / {label}</div><span class="eyebrow">PRIMEBOARD / {label.upper()}</span><h1 class="reveal">{title}</h1><div class="hero-bottom"><p>{desc}</p><a class="button lime" href="#explore">Explore the possibilities ↘</a></div><span class="page-star" aria-hidden="true">✳</span></section>'
def cta():
    return '<section class="page-cta section-pad"><span class="eyebrow">LET’S BUILD YOUR NEXT CHAPTER</span><h2 class="reveal">Your idea.<br><em>A world to meet.</em></h2><a class="button lime" href="mailto:info@primeboards.in?subject=Primeboard%20campaign%20enquiry">Talk to Primeboard ↗</a></section>'
def cards(items):
    return '<div class="feature-cards">'+''.join(f'<article class="reveal"><span>0{i+1} /</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(items))+'</div>'
def note(text): return f'<p class="preview-note">{text}</p>'
def creative(): return '<div class="demo-creative"><small>FICTIONAL CAMPAIGN / STUDIO NORTH</small><strong>Make room<br>for something<br><em>extraordinary.</em></strong><span class="creative-flower" aria-hidden="true">✳</span><span class="creative-cta">Discover the collection ↗</span></div>'
# Home retains its original visual composition, with a shared multi-page shell.
home=(root/'index.html').read_text(encoding='utf-8-sig')
home=re.sub(r'<header.*?</header>',nav,home,flags=re.S)
home=re.sub(r'<footer>.*?</footer>',footer,home,flags=re.S)
if 'pages.css' not in home: home=home.replace('</head>','<link rel="stylesheet" href="pages.css"><script src="pages.js" defer></script></head>')
home=home.replace('href="#partners"','href="partners.html"')
(root/'index.html').write_text(home,encoding='utf-8')
