content+='''<section id="explore" class="section-pad"><div class="section-heading"><h2>Same idea.<br><em>Different scale.</em></h2><p>Switch between physical and digital formats to imagine your campaign in the real world.</p></div><div class="preview-controls" aria-label="Outdoor preview"><button data-scene="static" aria-pressed="true">Static billboard</button><button data-scene="screen" aria-pressed="false">Digital screen</button></div><div class="outdoor-demo" data-scene="static"><img src="times-square-5913240_1280.jpg" alt="City streets with outdoor advertising" loading="lazy"><div class="demo-billboard">'''+creative()+'''</div><span class="scene-label">Static billboard · illustrative placement</span></div>'''+note('Concept preview, not available inventory. Actual artwork dimensions, installation and display schedules depend on the selected media owner.')+cards([('Pinpoint your audience','Explore location, neighbourhood, visibility and format before selecting a space.'),('Choose your format','Compare static boards, digital screens, sizes, durations and media packages.'),('Coordinate delivery','Plan creative, installation or screen scheduling, and request delivery updates.')])+'</section>'+cta()
page('billboards','Billboards & digital screens','Explore static billboard and digital-screen advertising with interactive placement previews.',content)
content=hero('Metro & trains','Your brand.<br><em>Along for the ride.</em>','Inside the coach. Across the station. Out on the route. Give everyday journeys something new to look at.','mint')
content+='''<section id="explore" class="section-pad"><div class="section-heading"><h2>Pick a place<br><em>in the journey.</em></h2><p>Explore three different transit environments. Routes, coach coverage and permitted formats are confirmed with the media owner.</p></div><div class="preview-controls"><button data-transit="exterior" aria-pressed="true">Train exterior</button><button data-transit="interior" aria-pressed="false">Inside the coach</button><button data-transit="station" aria-pressed="false">Station display</button></div><div class="transit-demo" data-transit="exterior"><div class="station-sign">PRIMEBOARD CENTRAL <span>PLATFORM 01 →</span></div><div class="train-body"><div class="train-windows"><i></i><i></i><i></i><i></i><i></i></div><div class="train-ad">MAKE EVERY JOURNEY EXTRAORDINARY. ✳</div><div class="train-wheels">● ● <span>● ●</span></div></div><div class="station-poster">'''+creative()+'''</div><div class="rail-track"></div></div><p class="preview-note" id="transit-caption" aria-live="polite">Exterior wrap · an illustrative campaign across the coach body.</p>'''+cards([('Routes & stations','Define the service, origin and destination, station and operating days.'),('Coverage & formats','Discuss coach count, interior panels, exterior coverage and digital screens.'),('Plans & approvals','Confirm authority permissions, artwork specifications and installation windows.')])+'</section>'+cta()
page('metro','Metro & train advertising','Explore exterior wraps, interior train advertising and station displays.',content)
groups=[('JioStar','Star Plus|Colors|National Geographic','https://www.jiostar.com/portfolio/'),('Sony Pictures Networks India','Sony Entertainment Television|Sony SAB|Sony Sports Ten 1','https://www.sonypicturesnetworks.com/overview'),('Zee Entertainment','Zee TV|Zee Cinema','https://www.zee.com/'),('News broadcasters','News channel planning by market','')]
